package com.researchdesk.research;
import java.net.*;import java.net.http.*;import java.nio.file.*;import java.util.*;
import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
/** Requires explicit isolated fixture server on generation-ai:8001 and API AI_BASE_URL override. */
class GenerationRaceIT extends RunRecoveryIT {
 void release(String run)throws Exception{String code="import urllib.request; r=urllib.request.Request('http://127.0.0.1:8001/release',data=b'{\"runId\":\""+run+"\"}',headers={'Content-Type':'application/json'}); urllib.request.urlopen(r).read()";var p=new ProcessBuilder("docker","compose","-p",com.researchdesk.ComposeFixture.project(),"-f",Path.of(System.getProperty("user.dir"),"../../infra/compose.yaml").normalize().toString(),"exec","-T","ai","python","-").redirectErrorStream(true).start();p.getOutputStream().write(code.getBytes(java.nio.charset.StandardCharsets.UTF_8));p.getOutputStream().close();String output=new String(p.getInputStream().readAllBytes());assertThat(p.waitFor()).as(output).isZero();}
 String create(String version)throws Exception{String body="{\"kind\":\"ANSWER\",\"projectId\":\""+project+"\",\"documentVersionIds\":"+(version==null?"[]":"[\""+version+"\"]")+",\"prompt\":\"controlled transaction race\"}";var r=request("POST","/api/runs",body);assertThat(r.statusCode()).as(r.body()).isEqualTo(202);return json.readTree(r.body()).get("runId").asText();}
 void awaitDraft(String run)throws Exception{long deadline=System.nanoTime()+30_000_000_000L;while(System.nanoTime()<deadline){var r=json.readTree(request("GET","/api/runs/"+run,null).body());if(r.get("text").asText().contains("Controlled draft"))return;assertThat(r.get("state").asText()).isIn("QUEUED","RUNNING");Thread.sleep(100);}throw new AssertionError("Fault fixture did not stream draft; verify AI_BASE_URL override");}
 @Test void cancelledRunCannotBecomeCompletedWhenProviderFinishesLate()throws Exception{String run=create(null);awaitDraft(run);assertThat(json.readTree(request("POST","/api/runs/"+run+"/cancel",null).body()).get("state").asText()).isEqualTo("CANCELLED");release(run);Thread.sleep(500);assertThat(json.readTree(request("GET","/api/runs/"+run,null).body()).get("state").asText()).isEqualTo("CANCELLED");assertThat(sql("SELECT count(*) FROM business.run_events WHERE run_id='"+run+"' AND type='completed'")).isEqualTo("0");}
 @Test void sourceDeletedBeforeFinalCommitFailsTheRun()throws Exception{String doc=UUID.randomUUID().toString(),version=UUID.randomUUID().toString();sql("INSERT INTO business.documents(id,project_id,title,content_sha256,state) VALUES ('"+doc+"','"+project+"','race source','"+"a".repeat(64)+"','READY'); INSERT INTO business.document_versions(id,document_id,project_id,object_key,media_type,size_bytes,parser_version) VALUES ('"+version+"','"+doc+"','"+project+"','race/"+version+"','text/markdown',10,'race-test')");String run=create(version);awaitDraft(run);sql("UPDATE business.documents SET state='DELETED' WHERE id='"+doc+"'");release(run);long deadline=System.nanoTime()+15_000_000_000L;while(System.nanoTime()<deadline){var body=json.readTree(request("GET","/api/runs/"+run,null).body());if(body.get("state").asText().equals("FAILED")){assertThat(body.get("error").get("code").asText()).isEqualTo("SOURCE_UNAVAILABLE");assertThat(sql("SELECT count(*) FROM business.run_events WHERE run_id='"+run+"' AND type='completed'")).isEqualTo("0");return;}Thread.sleep(100);}throw new AssertionError("Deleted source run did not fail");}
}
